package com.acid.camera;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.util.DisplayMetrics;
public class ScreenRecorderService extends Service {
 public static volatile boolean running=false;public static volatile String message;MediaProjection projection;MediaRecorder recorder;VirtualDisplay display;ParcelFileDescriptor descriptor;Uri uri;boolean stopping=false,started=false;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i==null||"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;
 NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("recording","Screen recording",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,ScreenRecorderService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notice=new Notification.Builder(this,"recording").setSmallIcon(studio.ellis.archivedesk.studio.R.drawable.acid_camera_icon).setContentTitle("ACID Camera · recording screen").setContentText("Tap STOP to finish and save").setOngoing(true).addAction(new Notification.Action.Builder(null,"STOP",stop).build()).build();startForeground(77,notice,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);
 try{ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,"ACID_screen_"+System.currentTimeMillis()+".mp4");v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");v.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/ACID Camera");v.put(MediaStore.Video.Media.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IllegalStateException("No media destination");descriptor=getContentResolver().openFileDescriptor(uri,"w");DisplayMetrics metrics=getResources().getDisplayMetrics();int w=metrics.widthPixels,h=metrics.heightPixels;if(Build.VERSION.SDK_INT>=30){android.graphics.Rect bounds=getSystemService(android.view.WindowManager.class).getMaximumWindowMetrics().getBounds();w=bounds.width();h=bounds.height();}float scale=Math.min(1f,1080f/Math.min(w,h));w=Math.max(2,(int)(w*scale)/2*2);h=Math.max(2,(int)(h*scale)/2*2);recorder=new MediaRecorder();recorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setOutputFile(descriptor.getFileDescriptor());recorder.setVideoEncoder(MediaRecorder.VideoEncoder.H264);recorder.setVideoSize(w,h);recorder.setVideoFrameRate(30);recorder.setVideoEncodingBitRate(8000000);recorder.prepare();recorder.setOnErrorListener((r,a,b)->{message="Recorder error; stopping";stopSelf();});projection=getSystemService(MediaProjectionManager.class).getMediaProjection(i.getIntExtra("result",Activity.RESULT_CANCELED),i.getParcelableExtra("data"));projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},new Handler(getMainLooper()));display=projection.createVirtualDisplay("ACID workspace",w,h,metrics.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,recorder.getSurface(),null,null);recorder.start();started=true;running=true;message="Screen recording started · no audio";}catch(Exception e){message="Recording failed: "+e.getMessage();stopSelf();}return START_NOT_STICKY;}
 public void onDestroy(){if(stopping)return;stopping=true;running=false;boolean good=false;if(recorder!=null){try{if(started){recorder.stop();good=true;}}catch(Exception e){message="Recording too short or interrupted; discarded";}try{recorder.release();}catch(Exception ignored){}}if(display!=null)display.release();if(projection!=null)projection.stop();if(descriptor!=null)try{descriptor.close();}catch(Exception ignored){}if(uri!=null){if(good){ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(uri,v,null,null);message="Recording saved / Movies · ACID Camera";}else getContentResolver().delete(uri,null,null);}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
